package com.holidayroster.calendar.domain;
import jakarta.persistence.*; import java.time.*; import java.util.Objects;
@Entity @Table(name="holiday") public class Holiday {
 public enum Status { ACTIVE, INACTIVE, CANCELLED } @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;
 @Column(name="holiday_name",nullable=false,length=160) private String name; @Column(name="holiday_date",nullable=false,unique=true) private LocalDate holidayDate; @Column(name="primary_count",nullable=false,columnDefinition="SMALLINT UNSIGNED") private short primaryCount; @Column(name="standby_count",nullable=false,columnDefinition="SMALLINT UNSIGNED") private short standbyCount; @Column(name="duty_window_start_utc") private LocalDateTime dutyWindowStart; @Column(name="duty_window_end_utc") private LocalDateTime dutyWindowEnd; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status; @Column(name="created_at_utc",nullable=false,updatable=false) private Instant createdAtUtc; @Column(name="updated_at_utc",nullable=false) private Instant updatedAtUtc; @Version @Column(name="row_version",nullable=false) private long rowVersion;
 protected Holiday(){} public Holiday(String n,LocalDate d,int p,int s,LocalDateTime start,LocalDateTime end,Instant now){apply(n,d,p,s,start,end);status=Status.ACTIVE;createdAtUtc=updatedAtUtc=Objects.requireNonNull(now);} public void update(String n,LocalDate d,int p,int s,LocalDateTime start,LocalDateTime end,Instant now){apply(n,d,p,s,start,end);updatedAtUtc=Objects.requireNonNull(now);} private void apply(String n,LocalDate d,int p,int s,LocalDateTime start,LocalDateTime end){if(n==null||n.isBlank()||n.trim().length()>160)throw new IllegalArgumentException("name is required and must be at most 160 characters.");if(d==null||p<1||s<0||p>Short.MAX_VALUE||s>Short.MAX_VALUE)throw new IllegalArgumentException("holiday date and explicit valid staffing counts are required.");if(start!=null&&end!=null&&end.isBefore(start))throw new IllegalArgumentException("dutyWindowEnd must not precede dutyWindowStart.");name=n.trim();holidayDate=d;primaryCount=(short)p;standbyCount=(short)s;dutyWindowStart=start;dutyWindowEnd=end;} public Long getId(){return id;} public String getName(){return name;} public LocalDate getHolidayDate(){return holidayDate;} public int getPrimaryCount(){return primaryCount;} public int getStandbyCount(){return standbyCount;} public LocalDateTime getDutyWindowStart(){return dutyWindowStart;} public LocalDateTime getDutyWindowEnd(){return dutyWindowEnd;} public Status getStatus(){return status;} public long getRowVersion(){return rowVersion;}}
